window.GRADES=window.GRADES||{};GRADES["2"]={subjects:[{"id":"ing","name":"Inglés","emo":"🇬🇧","tag":"Prueba de inglés","desc":"Programas de 1º y 2º · Open Day Starter y Open Day 1","c1":"#FF9F5A","c2":"#FF7A8A","units":[{"id":"e1","dot":"👋","name":"Hello!","title":"Hello! · colores y útiles","sub":"Saludos · nombre y edad · alfabeto · colores","rules":"\n<div class=\"rsec\"><h4>Hablar de vos</h4>\n<div class=\"rrow\"><span class=\"rl\">Para decir tu nombre</span><span class=\"ra\">My name's + nombre</span></div>\n<div class=\"rrow\"><span class=\"rl\">Para decir tu edad</span><span class=\"ra\">I'm + número</span></div>\n<p class=\"exline\">Ejemplo: un chico llamado Leo, de cinco años, diría <b>My name's Leo</b> y <b>I'm five</b>.</p></div>\n<div class=\"rsec\"><h4>Decir qué es algo</h4>\n<p class=\"exline\">Se empieza con <b>It's</b> (\"es\") y después va la cosa o el color: <b>It's a book. It's black.</b></p>\n<div class=\"warn\">Fijate qué te preguntan: si es <b>qué cosa es</b> o <b>de qué color es</b>.</div></div>","ex":[{"t":"choice","q":"Te vas de la escuela. ¿Qué decís?","o":["Goodbye!","Hello!","Thank you!"],"a":0},{"t":"choice","q":"<span class='en'>What's your name?</span>","o":["My name's Tom.","I'm six.","It's red."],"a":0},{"t":"choice","q":"<span class='en'>How old are you?</span>","h":"Tenés 7 años","o":["I'm seven.","I'm Tom.","It's seven."],"a":0},{"t":"match","q":"Uní cada color","pairs":[["pink","rosa"],["purple","violeta"],["grey","gris"],["blue","azul"],["red","rojo"],["green","verde"]]},{"t":"choice","e":"🟡","q":"<span class='en'>What colour is it?</span>","o":["It's yellow.","It's orange.","It's brown."],"a":0},{"t":"match","q":"Uní cada útil","pairs":[["pencil","lápiz"],["ruler","regla"],["crayon","crayón"],["pencil case","cartuchera"],["rubber","goma"]]},{"t":"choice","e":"🖊️","q":"<span class='en'>What is it?</span>","o":["It's a pen.","It's a pencil.","It's a ruler."],"a":0},{"t":"choice","q":"En el abecedario, ¿qué letra viene después de la <b>B</b>?","o":["C","D","A"],"a":0},{"t":"fill","q":"Escribí el número en inglés","labels":["3","8"],"a":["three","eight"]}]},{"id":"e2","dot":"🦁","name":"Animals","title":"Animals","sub":"It's a / an · Is it a…? · big / small","rules":"\n<div class=\"rsec\"><h4>A o AN</h4>\n<div class=\"rrow\"><span class=\"rl\">empieza con consonante</span><span class=\"ra\">a dog</span></div>\n<div class=\"rrow\"><span class=\"rl\">empieza con vocal (a, e, i, o, u)</span><span class=\"ra\">an orange</span></div></div>\n<div class=\"rsec\"><h4>Is it a…? (¿Es un…?)</h4>\n<div class=\"rrow\"><span class=\"rl\">Is it a cat? (sí)</span><span class=\"ra\">Yes, it's a cat.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Is it a cat? (no, es un perro)</span><span class=\"ra\">No, it's a dog.</span></div>\n<p class=\"exline\">En el NO se dice qué es en realidad.</p></div>\n<div class=\"rsec\"><h4>El color y el tamaño van ANTES</h4>\n<p class=\"exline\">En inglés se dice primero cómo es y después la cosa: <b>a red ball</b> (una pelota roja), nunca \"a ball red\".</p></div>","ex":[{"t":"match","q":"Uní cada animal","pairs":[["lion","león"],["monkey","mono"],["elephant","elefante"],["giraffe","jirafa"],["crocodile","cocodrilo"],["zebra","cebra"]]},{"t":"choice","e":"🐯","q":"<span class='en'>What is it?</span>","o":["It's a tiger.","It's a lion.","It's a hippo."],"a":0},{"t":"choice","e":"🦅","q":"It's ___ eagle.","o":["a","an"],"a":1},{"t":"choice","e":"🦛","q":"It's ___ hippo.","o":["a","an"],"a":0},{"t":"choice","e":"🚗","q":"<span class='en'>Is it a car?</span>","o":["Yes, it's a car.","No, it's a car.","Yes, it's a boat."],"a":0},{"t":"choice","e":"⛵","q":"<span class='en'>Is it a car?</span>","o":["No, it's a boat.","Yes, it's a boat.","No, it's a car."],"a":0},{"t":"choice","e":"🚙","q":"Es un auto azul: It's a ___.","o":["blue car","car blue"],"a":0},{"t":"choice","e":"🐘","q":"The elephant is ___.","o":["big","small"],"a":0},{"t":"choice","e":"🐭","q":"The mouse is ___.","o":["big","small"],"a":1}]},{"id":"e3","dot":"🙂","name":"Me","title":"Me · el cuerpo y cómo me siento","sub":"I've got · It's got · feelings · appearance","rules":"\n<div class=\"rsec\"><h4>I've got = yo tengo</h4>\n<div class=\"rrow\"><span class=\"rl\">I've got two hands.</span><span class=\"ra\">Tengo dos manos.</span></div>\n<div class=\"rrow\"><span class=\"rl\">A fish hasn't got hands.</span><span class=\"ra\">Un pez no tiene manos.</span></div>\n<p class=\"exline\">Para un animal o una cosa: <b>It's got</b> (tiene) y <b>It hasn't got</b> (no tiene).</p></div>\n<div class=\"rsec\"><h4>Cómo me siento: I'm…</h4>\n<p class=\"exline\"><b>I'm sad.</b> = Estoy triste. Primero <b>I'm</b>, después cómo estás.</p></div>\n<div class=\"rsec\"><h4>Describir el pelo</h4>\n<p class=\"exline\">Igual que con los colores, lo que describe va <b>antes</b>: <b>dark hair</b> (pelo oscuro).</p></div>","ex":[{"t":"match","q":"Uní cada parte de la cara","pairs":[["eyes","ojos"],["nose","nariz"],["mouth","boca"],["ears","orejas"],["hair","pelo"]]},{"t":"choice","e":"😀","q":"I'm ___.","o":["happy","sad","cold"],"a":0},{"t":"choice","e":"🥶","q":"I'm ___.","o":["hot","cold","happy"],"a":1},{"t":"choice","e":"🐍","q":"It ___ got legs.","o":["has","hasn't"],"a":1},{"t":"choice","e":"🐕","q":"It's got a ___.","o":["tail","wing"],"a":0},{"t":"choice","q":"Tenés el pelo largo: I've got ___ hair.","o":["long","short","curly"],"a":0},{"t":"choice","q":"¿Cuál significa «pelo rubio»?","o":["blond hair","dark hair","curly hair"],"a":0},{"t":"choice","q":"Tenés los ojos marrones: I've got ___ eyes.","o":["brown","blond","long"],"a":0}]},{"id":"e4","dot":"🏠","name":"Home & food","title":"Home & food","sub":"Where is…? · in / on / under · I like","rules":"\n<div class=\"rsec\"><h4>¿Dónde está?</h4>\n<div class=\"rrow\"><span class=\"rl\">Where is the dog?</span><span class=\"ra\">It's in the garden.</span></div>\n<p class=\"exline\">Se contesta con <b>It's</b> + dónde está.</p></div>\n<div class=\"rsec\"><h4>in · on · under</h4>\n<p class=\"exline\">Imaginate un pájaro y su jaula: si está <b>adentro</b> es una palabra, si está <b>arriba</b> es otra, y si está <b>abajo</b> es otra. Mirá bien el dibujo antes de elegir.</p></div>\n<div class=\"rsec\"><h4>Me gusta / no me gusta</h4>\n<div class=\"rrow\"><span class=\"rl\">I like cats.</span><span class=\"ra\">Me gustan los gatos.</span></div>\n<div class=\"rrow\"><span class=\"rl\">I don't like spiders.</span><span class=\"ra\">No me gustan las arañas.</span></div>\n<p class=\"exline\">Para decir que NO, se agrega <b>don't</b>.</p></div>","ex":[{"t":"match","q":"Uní cada palabra de la casa","pairs":[["bathroom","baño"],["bedroom","dormitorio"],["living room","living"],["fridge","heladera"],["cooker","cocina (para cocinar)"],["sofa","sofá"]]},{"t":"choice","e":"🐱📦","q":"El gato está ADENTRO de la caja: The cat is ___ the box.","o":["in","on","under"],"a":0},{"t":"choice","e":"⚽","q":"La pelota está DEBAJO de la mesa: The ball is ___ the table.","o":["in","on","under"],"a":2},{"t":"choice","e":"📕","q":"El libro está ARRIBA de la silla: The book is ___ the chair.","o":["in","on","under"],"a":1},{"t":"choice","q":"<span class='en'>Where is the ball?</span>","h":"Está en el dormitorio","o":["It's in the bedroom.","It's a bedroom.","It's bedroom."],"a":0},{"t":"choice","e":"😋🍕","q":"Me gusta la pizza.","o":["I like pizza.","I don't like pizza."],"a":0},{"t":"choice","e":"🤢🍌","q":"No me gustan las bananas.","o":["I like bananas.","I don't like bananas."],"a":1},{"t":"choice","q":"<span class='en'>Do you like…?</span> quiere decir…","o":["¿Te gusta…?","¿Tenés…?","¿Podés…?"],"a":0},{"t":"match","q":"Uní cada comida","pairs":[["cheese","queso"],["milk","leche"],["bread","pan"],["eggs","huevos"],["chicken","pollo"],["ice cream","helado"]]}]},{"id":"e5","dot":"👕","name":"Clothes & family","title":"Clothes, family & abilities","sub":"I'm wearing · auntie / uncle · I can / can't","rules":"\n<div class=\"rsec\"><h4>Lo que tengo puesto</h4>\n<p class=\"exline\"><b>I'm wearing blue shoes.</b> = Tengo puestos zapatos azules.</p></div>\n<div class=\"rsec\"><h4>He's o She's</h4>\n<div class=\"rrow\"><span class=\"rl\">varón</span><span class=\"ra\">He's my brother.</span></div>\n<div class=\"rrow\"><span class=\"rl\">mujer</span><span class=\"ra\">She's my sister.</span></div></div>\n<div class=\"rsec\"><h4>can / can't</h4>\n<div class=\"rrow\"><span class=\"rl\">I can jump.</span><span class=\"ra\">Puedo saltar.</span></div>\n<div class=\"rrow\"><span class=\"rl\">A cat can't talk.</span><span class=\"ra\">Un gato no puede hablar.</span></div>\n<div class=\"warn\">Pensá si de verdad <b>puede</b> o <b>no puede</b> hacerlo antes de elegir.</div></div>","ex":[{"t":"match","q":"Uní cada prenda","pairs":[["hat","gorro"],["coat","abrigo"],["boots","botas"],["gloves","guantes"],["sunglasses","anteojos de sol"],["trainers","zapatillas"]]},{"t":"choice","e":"👕","q":"I'm wearing a green ___.","o":["T-shirt","dress","hat"],"a":0},{"t":"match","q":"Uní cada familiar","pairs":[["mummy","mamá"],["daddy","papá"],["grandma","abuela"],["grandpa","abuelo"],["auntie","tía"],["uncle","tío"]]},{"t":"choice","q":"La hermana de mi mamá: She's my ___.","o":["auntie","uncle","sister"],"a":0},{"t":"choice","q":"El hermano de mi papá: ___ my uncle.","o":["He's","She's"],"a":0},{"t":"choice","e":"🐟","q":"Fish ___ swim.","o":["can","can't"],"a":0},{"t":"choice","e":"🐧","q":"Penguins ___ fly.","o":["can","can't"],"a":1},{"t":"choice","q":"Ella no sabe andar en bici: She ___ ride a bike.","o":["can","can't"],"a":1}]},{"id":"starter","dot":"👋","name":"Starter","title":"Starter Unit","sub":"Saludos, instrucciones y útiles","rules":"\n<div class=\"rsec\"><h4>Los saludos van de a pares</h4>\n<p class=\"exline\">Cada pregunta tiene su respuesta fija. Se memorizan juntas, como un par.</p>\n<div class=\"rrow\"><span class=\"rl\">Goodbye!</span><span class=\"ra\">See you tomorrow!</span></div>\n<p class=\"exline\">No hay regla que estudiar: hay que reconocer qué responde a qué.</p></div>\n<div class=\"rsec\"><h4>El apóstrofe borra una letra</h4>\n<div class=\"rrow\"><span class=\"rl\">He's</span><span class=\"ra\">= He is</span></div>\n<div class=\"rrow\"><span class=\"rl\">That's</span><span class=\"ra\">= That is</span></div>\n<p class=\"exline\">Siempre funciona igual: se junta el verbo con la palabra de antes y la letra que falta se reemplaza por el apóstrofe.</p></div>\n<div class=\"rsec\"><h4>Las instrucciones son órdenes</h4>\n<p class=\"exline\">El verbo va <b>primero y solo</b>, sin sujeto adelante.</p>\n<div class=\"rrow\"><span class=\"rl\">Listen!</span><span class=\"ra\">¡Escuchá!</span></div>\n<div class=\"warn\">Para traducir una instrucción, fijate en el <b>verbo</b>: es la primera palabra y es la que manda. Las que vienen después dicen sobre qué.</div></div>\n<div class=\"rsec\"><h4>Preguntar qué es algo</h4>\n<p class=\"exline\">A <b>What is it?</b> se contesta con <b>It's a</b> + el objeto.</p>\n<div class=\"rrow\"><span class=\"rl\">What is it?</span><span class=\"ra\">It's a box.</span></div></div>","ex":[{"t":"match","q":"Uní cada pregunta con su respuesta","pairs":[["What's your name?","My name's Ana."],["How are you?","I'm fine, thanks!"],["Hello!","Hi!"],["Good morning!","Good morning, Miss!"]]},{"t":"choice","q":"La maestra dice: <span class='en'>Stand up</span>","h":"¿Qué tenés que hacer?","o":["Pararme","Sentarme","Abrir el libro"],"a":0},{"t":"choice","q":"<span class='en'>Open your books</span> significa:","o":["Abran los libros","Cierren los libros","Guarden los lápices"],"a":0},{"t":"choice","q":"<span class='en'>Put away your pencils</span> significa:","o":["Saquen los lápices","Guarden los lápices","Presten los lápices"],"a":1},{"t":"choice","q":"<span class='en'>Sit down, please.</span>","o":["Sentate, por favor","Parate, por favor","Cerrá el libro"],"a":0},{"t":"choice","e":"✏️","q":"<span class='en'>What is it?</span>","o":["It's a pencil.","It's a pen.","It's a rubber."],"a":0},{"t":"choice","e":"🎒","q":"<span class='en'>What is it?</span>","o":["It's a ruler.","It's a schoolbag.","It's a book."],"a":1},{"t":"choice","q":"¿Cómo se dice <b>lapicera</b>?","o":["pencil","crayon","pen"],"a":2},{"t":"spell","q":"Escribí en inglés: <b>goma</b>","a":"rubber"},{"t":"spell","q":"Escribí en inglés: <b>regla</b>","a":"ruler"},{"t":"spell","q":"Escribí en inglés: <b>cartuchera</b>","a":"pencil case"},{"t":"choice","q":"<span class='en'>Take out your pencils</span> significa:","o":["Guarden los lápices","Saquen los lápices","Presten los lápices"],"a":1},{"t":"choice","q":"<span class='en'>Close your books</span> significa:","o":["Cierren los libros","Abran los libros","Lean los libros"],"a":0}]},{"id":"u1","dot":"🎂","name":"Unit 1","title":"Unit 1","sub":"How old are you? · he/she · colores y números","rules":"\n<div class=\"rsec\"><h4>El verbo TO BE</h4>\n<div class=\"rrow\"><span class=\"rl\">I</span><span class=\"ra\">am</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">is</span></div>\n<div class=\"rrow\"><span class=\"rl\">you / we / they</span><span class=\"ra\">are</span></div>\n<p class=\"exline\">The cat <b>is</b> small. &nbsp; We <b>are</b> at school.</p>\n<div class=\"warn\">La edad también se dice con <b>to be</b>, no con \"tener\": <b>He is eleven.</b> Literalmente \"él ES once\".</div></div>\n<div class=\"rsec\"><h4>Para preguntar, se da vuelta</h4>\n<div class=\"rrow\"><span class=\"rl\">The dog is big.</span><span class=\"ra\">Is the dog big?</span></div>\n<p class=\"exline\">El verbo salta al principio. Nada más cambia de lugar.</p></div>\n<div class=\"rsec\"><h4>Respuestas cortas</h4>\n<div class=\"rrow\"><span class=\"rl\">Is the dog big?</span><span class=\"ra\">Yes, it is. / No, it isn't.</span></div>\n<div class=\"warn\"><b>&#9888; En el SÍ nunca se contrae.</b><br>\n<span class=\"yes\">&#10003;</span> Yes, he <b>is</b>. &nbsp;&nbsp; <span class=\"no\">&#10007;</span> Yes, he's.<br>\nEn el NO sí se puede: No, he isn't.</div></div>\n<div class=\"rsec\"><h4>HIS o HER: mirá de quién es</h4>\n<div class=\"rrow\"><span class=\"rl\">Pablo &rarr; es varón</span><span class=\"ra\">his bike</span></div>\n<div class=\"rrow\"><span class=\"rl\">Lucía &rarr; es mujer</span><span class=\"ra\">her bike</span></div>\n<div class=\"warn\"><b>&#9888; La trampa:</b> en castellano los dos son <b>\"su\"</b>. En inglés no mirás la cosa, mirás <b>al dueño</b>. La bicicleta de Pablo es <b>his</b> bike aunque \"bicicleta\" sea femenino.</div></div>","ex":[{"t":"choice","q":"<span class='en'>How old are you?</span>","h":"Tenés 6 años","o":["I'm six years old.","I'm fine, thanks.","My name's Tom."],"a":0},{"t":"choice","q":"<span class='en'>Are you seven years old?</span>","h":"Respondé que SÍ","o":["Yes, I am.","Yes, I is.","Yes, I are."],"a":0},{"t":"choice","q":"<span class='en'>Are you seven?</span>","h":"Respondé que NO","o":["No, I not.","No, I'm not.","No, I aren't."],"a":1},{"t":"choice","q":"This is Tom. ___ is seven.","o":["He","She","I"],"a":0},{"t":"choice","q":"This is Mary. ___ isn't six.","o":["He","She","It"],"a":1},{"t":"choice","q":"<span class='en'>How old is she?</span>","h":"Ella tiene 6","o":["He's six.","She's six.","I'm six."],"a":1},{"t":"choice","q":"This is my friend Ben. ___ name is Ben.","o":["Her","His","Your"],"a":1},{"t":"choice","q":"This is Ana. ___ favourite colour is red.","o":["His","Her","My"],"a":1},{"t":"choice","q":"<span class='en'>What colour is your schoolbag?</span>","h":"Es azul 🟦","o":["It's green.","It's blue.","It's black."],"a":1},{"t":"match","q":"Uní el color con su nombre","pairs":[["red","🔴 rojo"],["yellow","🟡 amarillo"],["brown","🟤 marrón"],["orange","🟠 naranja"],["green","🟢 verde"],["black","⚫ negro"],["white","⚪ blanco"],["blue","🔵 azul"]]},{"t":"spell","q":"Escribí el número <b>7</b> en inglés","a":"seven"},{"t":"spell","q":"Escribí el número <b>4</b> en inglés","a":"four"},{"t":"spell","q":"Escribí el número <b>10</b> en inglés","a":"ten"},{"t":"match","q":"Uní cada número con su palabra","pairs":[["one","1"],["two","2"],["three","3"],["five","5"],["six","6"],["eight","8"],["nine","9"]]},{"t":"choice","q":"<span class='en'>What's your favourite colour?</span>","h":"Tu color favorito es el blanco","o":["My favourite colour is white.","I'm white.","It's favourite white."],"a":0}]},{"id":"u2","dot":"👨‍👩‍👧","name":"Unit 2","title":"Unit 2","sub":"We/They are · familia · adjetivos","rules":"\n<div class=\"rsec\"><h4>TO BE en plural</h4>\n<div class=\"rrow\"><span class=\"rl\">we / you / they</span><span class=\"ra\">are</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">is</span></div>\n<p class=\"exline\">You <b>are</b> my friends. &nbsp; The dogs <b>are</b> big.</p></div>\n<div class=\"rsec\"><h4>El negativo</h4>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">isn't</span></div>\n<div class=\"rrow\"><span class=\"rl\">we / you / they</span><span class=\"ra\">aren't</span></div>\n<p class=\"exline\">The cat <b>isn't</b> black. &nbsp; They <b>aren't</b> at home.</p></div>\n<div class=\"rsec\"><h4>Regla de oro de las respuestas cortas</h4>\n<p class=\"exline\">Se contesta con <b>el mismo verbo</b> con el que empieza la pregunta.</p>\n<div class=\"rrow\"><span class=\"rl\">Is it big?</span><span class=\"ra\">Yes, it is.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Are we late?</span><span class=\"ra\">No, we aren't.</span></div>\n<div class=\"warn\">Mirá la <b>primera palabra</b> de la pregunta: esa misma, conjugada igual, es la que va en la respuesta.</div></div>\n<div class=\"rsec\"><h4>Adjetivos</h4>\n<p class=\"exline\">Casi todos vienen en <b>pares opuestos</b>. Si te sale uno, pensá cuál sería su contrario: suele ser el que buscás.</p></div>","ex":[{"t":"choice","q":"We ___ tall.","o":["am","is","are"],"a":2},{"t":"choice","q":"They ___ young.","o":["is","are","am"],"a":1},{"t":"choice","q":"<span class='en'>Are they happy?</span>","h":"Respondé que SÍ","o":["Yes, they are.","Yes, they aren't.","Yes, they is."],"a":0},{"t":"choice","q":"<span class='en'>Is he your brother?</span>","h":"Respondé que NO","o":["No, he aren't.","No, he not.","No, he isn't."],"a":2},{"t":"choice","q":"We ___ old. (negativo)","o":["aren't","isn't","not"],"a":0},{"t":"choice","q":"<span class='en'>Is she your sister?</span>","h":"Respondé que SÍ","o":["Yes, she is.","Yes, she are.","Yes, he is."],"a":0},{"t":"match","q":"Uní cada palabra con su significado","pairs":[["mum","mamá"],["dad","papá"],["sister","hermana"],["grandma","abuela"],["grandpa","abuelo"],["brother","hermano"],["dog","perro"],["family","familia"]]},{"t":"choice","q":"Lo contrario de <span class='en'>tall</span> es:","o":["small","short","young"],"a":1},{"t":"choice","q":"Lo contrario de <span class='en'>happy</span> es:","o":["sad","old","tall"],"a":0},{"t":"choice","q":"Lo contrario de <span class='en'>young</span> es:","o":["short","small","old"],"a":2},{"t":"spell","q":"Escribí en inglés: <b>hermana</b>","a":"sister"},{"t":"spell","q":"Escribí en inglés: <b>abuelo</b>","a":"grandpa"},{"t":"choice","q":"¿Cómo se dice <b>hermanito bebé</b>?","o":["baby brother","baby sister","little brother"],"a":0}]},{"id":"u3","dot":"🏠","name":"Unit 3","title":"Unit 3","sub":"There is / There are · preposiciones · la casa","rules":"\n<div class=\"rsec\"><h4>There is / There are = \"hay\"</h4>\n<div class=\"rrow\"><span class=\"rl\">1 sola cosa</span><span class=\"ra\">There is</span></div>\n<div class=\"rrow\"><span class=\"rl\">2 o más</span><span class=\"ra\">There are</span></div>\n<p class=\"exline\">There <b>is</b> a dog in the garden. &nbsp; There <b>are</b> three birds.</p>\n<div class=\"warn\"><b>&#9888; Truco rápido:</b> si el sustantivo termina en <b>-s</b>, va <b>are</b>. Si no, va <b>is</b>.</div></div>\n<div class=\"rsec\"><h4>Preguntas y respuestas</h4>\n<div class=\"rrow\"><span class=\"rl\">Is there a garden? (no)</span><span class=\"ra\">No, there isn't.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Are there any trees? (sí)</span><span class=\"ra\">Yes, there are.</span></div>\n<p class=\"exline\">En la respuesta se repiten <b>there</b> y el mismo verbo de la pregunta (<b>is</b> o <b>are</b>). Para el SÍ va sin negación; para el NO, con <b>n't</b>.</p></div>\n<div class=\"rsec\"><h4>How many…? (cuántos)</h4>\n<div class=\"rrow\"><span class=\"rl\">How many birds are there?</span><span class=\"ra\">There are three.</span></div>\n<p class=\"exline\">Después de <b>How many</b> el sustantivo va en <b>plural</b>, y se contesta con <b>There are</b> + el número.</p></div>\n<div class=\"rsec\"><h4>Preposiciones: el lugar exacto importa</h4>\n<p class=\"exline\">Dos que se confunden todo el tiempo:</p>\n<div class=\"rrow\"><span class=\"rl\">The bird is <b>in</b> the cage</span><span class=\"ra\">adentro</span></div>\n<div class=\"rrow\"><span class=\"rl\">The bird is <b>on</b> the cage</span><span class=\"ra\">tocando la superficie</span></div>\n<div class=\"warn\"><b>&#9888; between</b> necesita siempre <b>dos</b> cosas, una de cada lado. Si hay una sola referencia, no puede ser <i>between</i>.<br>\nAntes de contestar, imaginate la escena y preguntate: ¿adentro, arriba, abajo, atrás, adelante, al costado, o en el medio de dos?</div></div>","ex":[{"t":"choice","q":"There ___ a sofa in the living room.","o":["is","are"],"a":0},{"t":"choice","q":"There ___ four rooms.","o":["is","are"],"a":1},{"t":"choice","q":"There ___ two chairs.","o":["is","are"],"a":1},{"t":"choice","q":"<span class='en'>Is there a ladder?</span>","h":"Respondé que SÍ","o":["Yes, there is.","Yes, there are.","Yes, it is."],"a":0},{"t":"choice","q":"<span class='en'>Are there any stairs?</span>","h":"Respondé que NO","o":["No, there isn't.","No, there aren't.","No, they aren't."],"a":1},{"t":"choice","q":"<span class='en'>How many chairs are there?</span>","h":"Hay 6","o":["There is six.","There are six.","They are six."],"a":1},{"t":"choice","e":"🐱📦","q":"El gato está <b>ADENTRO</b> de la caja.","o":["The cat is in the box.","The cat is on the box.","The cat is under the box."],"a":0},{"t":"choice","q":"El perro está <b>DEBAJO</b> de la mesa.","o":["behind the table","under the table","next to the table"],"a":1},{"t":"choice","q":"La pelota está <b>ENTRE</b> las dos sillas.","o":["in front of the chairs","behind the chairs","between the chairs"],"a":2},{"t":"choice","q":"La lámpara está <b>AL LADO</b> de la cama.","o":["next to the bed","under the bed","on the bed"],"a":0},{"t":"choice","q":"El cuadro está <b>DETRÁS</b> del sofá.","o":["in front of the sofa","behind the sofa","on the sofa"],"a":1},{"t":"match","q":"Uní cada habitación con su nombre","pairs":[["kitchen","cocina"],["bathroom","baño"],["bedroom","dormitorio"],["dining room","comedor"],["living room","living"]]},{"t":"choice","q":"¿En qué habitación cocinás?","o":["in the bathroom","in the kitchen","in the hall"],"a":1},{"t":"spell","q":"Escribí en inglés: <b>sillón</b>","a":"armchair"},{"t":"spell","q":"Escribí en inglés: <b>reloj</b>","a":"clock"},{"t":"match","q":"Uní cada mueble con su nombre","pairs":[["table","mesa"],["phone","teléfono"],["picture","cuadro"],["radio","la radio"],["television","televisión"],["sofa","sofá"]]},{"t":"choice","q":"<span class='en'>Where is the phone?</span>","h":"Está ARRIBA de la mesa","o":["It's on the table.","It's in the table.","It's under the table."],"a":0}]},{"id":"u4","dot":"🧸","name":"Unit 4","title":"Unit 4","sub":"I like / He likes · juguetes · el dormitorio","rules":"\n<div class=\"rsec\"><h4>La S de he / she / it</h4>\n<div class=\"rrow\"><span class=\"rl\">I / you / we / they</span><span class=\"ra\">like</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">like<b>s</b></span></div>\n<p class=\"exline\">My cousin <b>likes</b> music. &nbsp; We <b>like</b> music.</p></div>\n<div class=\"rsec\"><h4>El negativo</h4>\n<div class=\"rrow\"><span class=\"rl\">I / you / we / they</span><span class=\"ra\">don't</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">doesn't</span></div>\n<p class=\"exline\">We <b>don't</b> like rain. &nbsp; It <b>doesn't</b> like water.</p></div>\n<div class=\"rsec\"><h4>La pregunta</h4>\n<div class=\"rrow\"><span class=\"rl\">Do they like school?</span><span class=\"ra\">Yes, they do. / No, they don't.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Does your dad like tea?</span><span class=\"ra\">Yes, he does. / No, he doesn't.</span></div></div>\n<div class=\"rsec\"><h4>&#11088; La regla más importante de la unidad</h4>\n<div class=\"warn\"><b>La S aparece UNA sola vez por frase.</b> Si ya está en <b>does</b> o <b>doesn't</b>, el verbo va limpio.<br><br>\n<span class=\"yes\">&#10003;</span> She play<b>s</b> tennis.<br>\n<span class=\"yes\">&#10003;</span> She <b>doesn't play</b> tennis. &nbsp; <span class=\"no\">&#10007;</span> She doesn't <span class=\"no\">plays</span>.<br>\n<span class=\"yes\">&#10003;</span> <b>Does</b> she <b>play</b> tennis? &nbsp; <span class=\"no\">&#10007;</span> Does she <span class=\"no\">plays</span>?<br><br>\n<b>Truco:</b> \"does le roba la S al verbo\".</div></div>","ex":[{"t":"choice","q":"I ___ dolls. 😍","o":["like","likes"],"a":0},{"t":"choice","q":"He ___ robots. 😍","o":["like","likes"],"a":1},{"t":"choice","q":"She ___ like trucks. 🙅","o":["don't","doesn't"],"a":1},{"t":"choice","q":"I ___ like trains. 🙅","o":["don't","doesn't"],"a":0},{"t":"choice","q":"<span class='en'>Do you like monsters?</span>","h":"Respondé que SÍ","o":["Yes, I do.","Yes, I like.","Yes, I does."],"a":0},{"t":"choice","q":"<span class='en'>Does she like teddy bears?</span>","h":"Respondé que NO","o":["No, she don't.","No, she doesn't.","No, she isn't."],"a":1},{"t":"choice","q":"___ he like cars?","o":["Do","Does"],"a":1},{"t":"choice","q":"___ you like dolls?","o":["Do","Does"],"a":0},{"t":"match","q":"Uní cada juguete con su significado","pairs":[["ball","pelota"],["doll","muñeca"],["teddy bear","osito"],["truck","camión"],["bike","bicicleta"],["boat","barco"]]},{"t":"choice","e":"🛏️","q":"¿Dónde dormís?","o":["in the bed","on the desk","on the rug"],"a":0},{"t":"spell","q":"Escribí en inglés: <b>ventana</b>","a":"window"},{"t":"spell","q":"Escribí en inglés: <b>espejo</b>","a":"mirror"},{"t":"spell","q":"Escribí en inglés: <b>lámpara</b>","a":"lamp"},{"t":"match","q":"Uní cada cosa del dormitorio","pairs":[["bookcase","biblioteca"],["door","puerta"],["wall","pared"],["desk","escritorio"],["rug","alfombra"],["bed","cama"]]}]},{"id":"u5","dot":"🐴","name":"Unit 5","title":"Unit 5","sub":"Can · animales de granja · comida","rules":"\n<div class=\"rsec\"><h4>CAN es igual para todos</h4>\n<p class=\"exline\">No cambia nunca y <b>no lleva S</b>, ni siquiera con he / she / it.</p>\n<div class=\"rrow\"><span class=\"rl\">My brother <b>can</b> dance.</span><span class=\"ra\">nunca \"cans\"</span></div>\n<p class=\"exline\">El verbo que viene después va <b>solo</b>, sin \"to\": can <b>jump</b>, can <b>sing</b>.</p></div>\n<div class=\"rsec\"><h4>Negativo y pregunta con CAN</h4>\n<div class=\"rrow\"><span class=\"rl\">negativo</span><span class=\"ra\">can't</span></div>\n<div class=\"rrow\"><span class=\"rl\">Can it climb?</span><span class=\"ra\">Yes, it can. / No, it can't.</span></div></div>\n<div class=\"rsec\"><h4>Hechos: lo que pasa siempre</h4>\n<div class=\"rrow\"><span class=\"rl\">plural (varios)</span><span class=\"ra\">Cats sleep a lot.</span></div>\n<div class=\"rrow\"><span class=\"rl\">singular (uno)</span><span class=\"ra\">A cat sleep<b>s</b> a lot.</span></div>\n<p class=\"exline\">Es la misma S de la Unit 4. Para preguntar se usan <b>Do</b> y <b>Does</b>, con la misma división.</p></div>\n<div class=\"rsec\"><h4>&#9888; No mezclar CAN con DO</h4>\n<div class=\"warn\">La respuesta corta repite el verbo con el que <b>empieza</b> la pregunta.<br>\nCan you dance? &rarr; <span class=\"yes\">Yes, I can</span>, nunca <span class=\"no\">Yes, I do</span>.<br>\nDo you dance? &rarr; <span class=\"yes\">Yes, I do</span>, nunca <span class=\"no\">Yes, I can</span>.</div></div>","ex":[{"t":"choice","e":"🐦","q":"Birds ___ fly.","o":["can","can't"],"a":0},{"t":"choice","e":"🐴","q":"Horses ___ fly.","o":["can","can't"],"a":1},{"t":"choice","q":"<span class='en'>Can you swim?</span>","h":"Respondé que SÍ","o":["Yes, I can.","Yes, I do.","Yes, I am."],"a":0},{"t":"choice","q":"<span class='en'>Can you fly?</span>","h":"Respondé que NO","o":["No, I don't.","No, I can't.","No, I am not."],"a":1},{"t":"choice","q":"Horses ___ grass.","o":["eat","eats"],"a":0},{"t":"choice","q":"<span class='en'>Do they eat meat?</span>","h":"Los caballos NO comen carne","o":["No, they don't.","No, they aren't.","No, they can't."],"a":0},{"t":"choice","q":"<span class='en'>Do we eat carrots?</span>","h":"Respondé que SÍ","o":["Yes, we can.","Yes, we do.","Yes, we are."],"a":1},{"t":"match","q":"Uní cada animal con su nombre","pairs":[["cow","vaca"],["duck","pato"],["sheep","oveja"],["goat","cabra"],["donkey","burro"],["chicken","gallina"]]},{"t":"choice","e":"🍉","q":"<span class='en'>What is it?</span>","o":["It's a watermelon.","It's a lettuce.","It's corn."],"a":0},{"t":"choice","e":"🐰🥕","q":"Rabbits eat ___.","o":["meat","bread","carrots"],"a":2},{"t":"choice","q":"El elefante es muy ___.","o":["strong","tired","smart"],"a":0},{"t":"spell","q":"Escribí en inglés: <b>maíz</b>","a":"corn"},{"t":"spell","q":"Escribí en inglés: <b>pan</b>","a":"bread"},{"t":"match","q":"Uní cada comida con su nombre","pairs":[["apples","manzanas"],["tomatoes","tomates"],["bread","pan"],["lettuce","lechuga"],["watermelons","sandías"],["corn","maíz"]]},{"t":"choice","e":"🍌","q":"<span class='en'>What is it?</span>","o":["It's a banana.","It's an apple.","It's corn."],"a":0}]},{"id":"u6","dot":"🐞","name":"Unit 6","title":"Unit 6","sub":"Have got · this/that/these/those · el cuerpo","rules":"\n<div class=\"rsec\"><h4>HAVE GOT = tener</h4>\n<p class=\"exline\">Son <b>dos palabras que van siempre juntas</b> y significan una sola cosa: tener.</p>\n<div class=\"rrow\"><span class=\"rl\">I / you / we / they</span><span class=\"ra\">have got</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">has got</span></div>\n<p class=\"exline\">I <b>have got</b> two brothers. &nbsp; My friend <b>has got</b> a bike.</p></div>\n<div class=\"rsec\"><h4>&#11088; \"GOT\" no cambia nunca</h4>\n<div class=\"warn\">Lo único que se mueve es <b>have</b> / <b>has</b>. La palabra <b>got</b> se escribe siempre igual.<br>\nNo existen <span class=\"no\">\"hases\"</span>, <span class=\"no\">\"gots\"</span> ni <span class=\"no\">\"haves\"</span>.</div></div>\n<div class=\"rsec\"><h4>Negativo, pregunta y respuesta corta</h4>\n<div class=\"rrow\"><span class=\"rl\">negativo</span><span class=\"ra\">haven't got / hasn't got</span></div>\n<div class=\"rrow\"><span class=\"rl\">Has she got a sister?</span><span class=\"ra\">Yes, she has. / No, she hasn't.</span></div>\n<div class=\"warn\"><b>&#9888; En la respuesta corta NO se repite \"got\".</b><br>\n<span class=\"yes\">&#10003;</span> Yes, they <b>have</b>. &nbsp;&nbsp; <span class=\"no\">&#10007;</span> Yes, they have <span class=\"no\">got</span>.</div></div>\n<div class=\"rsec\"><h4>This / That / These / Those</h4>\n<div class=\"rrow\"><span class=\"rl\">cerca — 1</span><span class=\"ra\">this</span></div>\n<div class=\"rrow\"><span class=\"rl\">cerca — varios</span><span class=\"ra\">these</span></div>\n<div class=\"rrow\"><span class=\"rl\">lejos — 1</span><span class=\"ra\">that</span></div>\n<div class=\"rrow\"><span class=\"rl\">lejos — varios</span><span class=\"ra\">those</span></div>\n<p class=\"exline\"><b>This</b> is a book. &nbsp; <b>These</b> are books. &nbsp; <b>That</b> is a tree. &nbsp; <b>Those</b> are trees.</p>\n<div class=\"warn\"><b>Truco:</b> <b>these</b> y <b>those</b> terminan en <b>-se</b> &rarr; son los plurales. Y si la palabra es plural, el verbo también: These <b>are</b>, Those <b>are</b>.</div></div>","ex":[{"t":"choice","q":"I ___ got a dog.","o":["have","has"],"a":0},{"t":"choice","q":"A snake ___ got any legs. 🐍","o":["haven't","hasn't"],"a":1},{"t":"choice","q":"<span class='en'>Have you got any lizards?</span>","h":"Respondé que SÍ","o":["Yes, I have.","Yes, I has.","Yes, I am."],"a":0},{"t":"choice","q":"<span class='en'>Has it got any legs?</span>","h":"Respondé que NO","o":["No, it haven't.","No, it hasn't.","No, it isn't."],"a":1},{"t":"choice","q":"___ this a spider?","o":["Is","Are"],"a":0},{"t":"choice","q":"___ these butterflies?","o":["Is","Are"],"a":1},{"t":"choice","e":"🐝🐝","q":"Cerca y en plural: ___ are bees.","o":["This","These","That"],"a":1},{"t":"choice","e":"🦋🦋","q":"Lejos y en plural: ___ are butterflies.","o":["These","That","Those"],"a":2},{"t":"choice","e":"🐭","q":"Cerca y singular: ___ is a mouse.","o":["This","These","Those"],"a":0},{"t":"choice","q":"¿Cómo preguntás por varias cosas?","o":["What is these?","What are these?","What are this?"],"a":1},{"t":"match","q":"Uní cada bichito con su nombre","pairs":[["bee","abeja"],["frog","rana"],["spider","araña"],["butterfly","mariposa"],["ladybug","vaquita de San Antonio"],["caterpillar","oruga"]]},{"t":"match","q":"Uní cada parte del cuerpo","pairs":[["head","cabeza"],["hand","mano"],["leg","pierna"],["mouth","boca"],["ear","oreja"],["nose","nariz"]]},{"t":"choice","q":"El plural de <span class='en'>foot</span> es:","o":["foots","feet","footes"],"a":1},{"t":"spell","q":"Escribí en inglés: <b>ojo</b>","a":"eye"},{"t":"spell","q":"Escribí en inglés: <b>pelo</b>","a":"hair"},{"t":"spell","q":"Escribí en inglés: <b>brazo</b>","a":"arm"}]},{"id":"resumen","dot":"U0001F4CB","name":"Resumen","title":"Resumen general","sub":"¿Cuándo uso cada uno? — la chuleta final","rules":"\n<div class=\"rsec\"><h4>1. ¿Qué querés decir?</h4>\n<div class=\"rrow\"><span class=\"rl\">ser, estar, edad, cómo es algo</span><span class=\"ra\">am / is / are</span></div>\n<div class=\"rrow\"><span class=\"rl\">tener algo</span><span class=\"ra\">have got / has got</span></div>\n<div class=\"rrow\"><span class=\"rl\">gustar, comer, acciones y hechos</span><span class=\"ra\">do / does</span></div>\n<div class=\"rrow\"><span class=\"rl\">poder o saber hacer</span><span class=\"ra\">can</span></div>\n<div class=\"rrow\"><span class=\"rl\">hay cosas en un lugar</span><span class=\"ra\">there is / there are</span></div></div>\n<div class=\"rsec\"><h4>2. ¿Quién hace la acción? Hay dos grupos</h4>\n<div class=\"rrow\"><span class=\"rl\"><b>Grupo A</b> — I, you, we, they</span><span class=\"ra\">are · have got · like · do</span></div>\n<div class=\"rrow\"><span class=\"rl\"><b>Grupo B</b> — he, she, it</span><span class=\"ra\">is · has got · likes · does</span></div>\n<div class=\"warn\"><b>El Grupo B es el de la S:</b> i<b>s</b>, ha<b>s</b>, like<b>s</b>, doe<b>s</b>. Si el sujeto es él, ella, un animal o una cosa, casi todo lleva S.<br>\n(<b>I</b> es la excepción: va con <b>am</b>.)</div></div>\n<div class=\"rsec\"><h4>3. Las respuestas cortas repiten el verbo de la pregunta</h4>\n<p class=\"exline\">Mirá con qué palabra <b>empieza</b> la pregunta y contestá con esa misma:</p>\n<div class=\"rrow\"><span class=\"rl\">Is… / Are… / Am…</span><span class=\"ra\">… is / are / am</span></div>\n<div class=\"rrow\"><span class=\"rl\">Do… / Does…</span><span class=\"ra\">… do / does</span></div>\n<div class=\"rrow\"><span class=\"rl\">Have… / Has…</span><span class=\"ra\">… have / has</span></div>\n<div class=\"rrow\"><span class=\"rl\">Can…</span><span class=\"ra\">… can</span></div>\n<div class=\"warn\"><b>&#9888; El error más común de toda la prueba</b> es contestar con el verbo equivocado. Antes de responder, tapá la pregunta con el dedo salvo la primera palabra: esa manda.</div></div>","ex":[]}]},{"id":"mate","name":"Matemática","emo":"🔢","tag":"","desc":"Cálculos, números hasta 100 y problemas","c1":"#3F8FE8","c2":"#4FB9DB","units":[{"id":"m1","dot":"⚡","name":"Cálculos fáciles","title":"Cálculos que conviene saber de memoria","sub":"+1 y −1 · dobles · los que dan 10 · decenas · +10","rules":"\n<div class=\"rsec\"><h4>Sumar o restar 1</h4>\n<p class=\"exline\">Sumar 1 es decir <b>el número que sigue</b>. Restar 1 es decir <b>el que viene antes</b>. Ejemplo: 26 + 1 = 27.</p></div>\n<div class=\"rsec\"><h4>Dobles</h4>\n<p class=\"exline\">Un doble es sumar <b>el mismo número dos veces</b>: 4 + 4 = 8. Conviene saberlos de memoria.</p></div>\n<div class=\"rsec\"><h4>Los que dan 10</h4>\n<p class=\"exline\">Son parejas de números que juntos forman 10, como <b>1 + 9</b>. Usá los dedos de las dos manos para encontrarlas.</p></div>\n<div class=\"rsec\"><h4>Sumar 10</h4>\n<div class=\"warn\">Cuando sumás 10, <b>solo cambia la cifra de adelante</b> (las decenas): 46 + 10 = <b>5</b>6. La de atrás queda igual.</div></div>","ex":[{"t":"fill","q":"Uno más y uno menos","labels":["8 + 1","15 + 1","20 − 1","43 − 1"],"a":["9","16","19","42"]},{"t":"fill","q":"Dobles","labels":["3 + 3","5 + 5","7 + 7","9 + 9"],"a":["6","10","14","18"]},{"t":"fill","q":"Completá para que dé 10","labels":["6 + __","3 + __","__ + 8","5 + __"],"a":["4","7","2","5"]},{"t":"fill","q":"Decenas más unidades","labels":["20 + 4","50 + 7","30 + 9","80 + 1"],"a":["24","57","39","81"]},{"t":"fill","q":"Sumá 10","labels":["12 + 10","35 + 10","8 + 10","60 + 10"],"a":["22","45","18","70"]},{"t":"fill","q":"Restá 10","labels":["40 − 10","27 − 10","90 − 10"],"a":["30","17","80"]}]},{"id":"m2","dot":"🔢","name":"Números hasta 100","title":"Números hasta 100","sub":"Cuadro de números · anterior y siguiente · comparar · decenas","rules":"\n<div class=\"rsec\"><h4>El cuadro de números</h4>\n<div class=\"rrow\"><span class=\"rl\">un lugar a la derecha</span><span class=\"ra\">+1</span></div>\n<div class=\"rrow\"><span class=\"rl\">un lugar a la izquierda</span><span class=\"ra\">−1</span></div>\n<div class=\"rrow\"><span class=\"rl\">un lugar abajo</span><span class=\"ra\">+10</span></div>\n<div class=\"rrow\"><span class=\"rl\">un lugar arriba</span><span class=\"ra\">−10</span></div>\n<p class=\"exline\">Ejemplo: abajo del 12 está el 22.</p></div>\n<div class=\"rsec\"><h4>Decenas y unidades</h4>\n<p class=\"exline\">En <b>75</b>, el 7 son <b>decenas</b> (grupos de 10) y el 5 son <b>unidades</b> (sueltos).</p></div>\n<div class=\"rsec\"><h4>¿Cuál es mayor?</h4>\n<div class=\"warn\">Mirá primero <b>la cifra de adelante</b>. El que tiene más decenas es el mayor: 31 &gt; 29. Si las decenas son iguales, mirá las unidades.</div></div>","ex":[{"t":"fill","q":"¿Qué número sigue?","labels":["29 →","59 →","99 →"],"a":["30","60","100"]},{"t":"fill","q":"¿Qué número va antes?","labels":["→ 40","→ 71","→ 100"],"a":["39","70","99"]},{"t":"fill","q":"En el cuadro de números, ¿qué número está…?","labels":["abajo del 34","arriba del 57","a la derecha del 68","a la izquierda del 90"],"a":["44","47","69","89"]},{"t":"choice","q":"47 ___ 74","o":["&lt;","&gt;","="],"a":0},{"t":"choice","q":"60 ___ 59","o":["&lt;","&gt;","="],"a":1},{"t":"choice","q":"¿Cuál es el número más grande?","o":["38","83","58"],"a":1},{"t":"order","q":"Ordená de menor a mayor","items":["52","25","70","7","61"],"a":["7","25","52","61","70"]},{"t":"fill","q":"El número 63 tiene…","labels":["Decenas","Unidades"],"a":["6","3"]},{"t":"fill","q":"Escribí el número que tiene 4 decenas y 8 unidades","labels":[""],"a":["48"]},{"t":"fill","q":"Escribí con palabras","labels":["15","40"],"a":["quince","cuarenta"]}]},{"id":"m3","dot":"🧩","name":"Problemas","title":"Problemas de sumar y restar","sub":"Agregar · avanzar · juntar · quitar · retroceder","rules":"\n<div class=\"rsec\"><h4>¿Qué pasa en el problema?</h4>\n<div class=\"rrow\"><span class=\"rl\">me dan más, avanzo, junto</span><span class=\"ra\">SUMA</span></div>\n<div class=\"rrow\"><span class=\"rl\">me sacan, pierdo, retrocedo</span><span class=\"ra\">RESTA</span></div>\n<p class=\"exline\">Ejemplo: \"Tenía 5 autitos y me regalaron 2\" &rarr; me dieron más &rarr; 5 + 2.</p>\n<div class=\"warn\"><b>Revisá:</b> si te dieron cosas, tenés que terminar con <b>más</b> que antes. Si te sacaron, con <b>menos</b>.</div></div>","ex":[{"t":"fill","q":"Tenía <b>8</b> caramelos y me regalaron <b>5</b>. ¿Cuántos tengo ahora?","labels":["Respuesta"],"a":["13"]},{"t":"fill","q":"En el colectivo había <b>15</b> personas y bajaron <b>6</b>. ¿Cuántas quedaron?","labels":["Respuesta"],"a":["9"]},{"t":"fill","q":"En el juego estoy en el casillero <b>12</b> y avanzo <b>6</b>. ¿A qué casillero llego?","labels":["Respuesta"],"a":["18"]},{"t":"fill","q":"Yo tengo <b>9</b> figuritas y mi hermano tiene <b>7</b>. ¿Cuántas tenemos entre los dos?","labels":["Respuesta"],"a":["16"]},{"t":"fill","q":"Estaba en el casillero <b>20</b> y retrocedí <b>4</b>. ¿Dónde quedé?","labels":["Respuesta"],"a":["16"]},{"t":"choice","q":"Tenía <b>14</b> globos y se volaron <b>5</b>. ¿Qué cuenta hay que hacer?","o":["14 + 5","14 − 5"],"a":1},{"t":"fill","q":"Entonces, ¿cuántos globos me quedaron?","labels":["Respuesta"],"a":["9"]},{"t":"choice","q":"¿Qué problema se resuelve con una <b>resta</b>?","o":["Tengo 6 lápices y me dan 3","Tengo 10 lápices y pierdo 2","Tengo 4 lápices rojos y 5 azules"],"a":1}]},{"id":"m4","dot":"🧱","name":"Descomponer","title":"Calcular descomponiendo","sub":"Separar en decenas y unidades","rules":"\n<div class=\"rsec\"><h4>Descomponer un número</h4>\n<p class=\"exline\">Es separarlo en decenas y unidades: <b>25 = 20 + 5</b>.</p></div>\n<div class=\"rsec\"><h4>Sumar descomponiendo</h4>\n<div class=\"rrow\"><span class=\"rl\">25 + 13</span><span class=\"ra\">(20 + 10) + (5 + 3)</span></div>\n<div class=\"rrow\"><span class=\"rl\"></span><span class=\"ra\">30 + 8 = 38</span></div>\n<p class=\"exline\">Se suman las decenas con las decenas y las unidades con las unidades. Al final se juntan.</p></div>","ex":[{"t":"fill","q":"Descomponé","labels":["36 =","58 =","71 ="],"a":["30+6","50+8","70+1"]},{"t":"fill","q":"Resolvé descomponiendo","labels":["23 + 14","41 + 35","56 + 22"],"a":["37","76","78"]},{"t":"fill","q":"Restá descomponiendo","labels":["47 − 23","68 − 35"],"a":["24","33"]},{"t":"open","q":"Contá cómo hiciste la cuenta 23 + 14","model":"Lo que se busca: que separe decenas y unidades (20 + 10 y 3 + 4) y que junte los resultados. Si lo hizo de otra forma y llegó bien, también vale: pedile que lo explique."}]},{"id":"msim","dot":"📝","name":"Simulacro","title":"Simulacro de examen","sub":"Todo junto · sin mirar los ejemplos","rules":"\n<div class=\"rsec\"><h4>Antes de empezar</h4>\n<p class=\"exline\">Leé cada consigna dos veces. Si un problema cuesta, hacé un dibujo o usá los dedos.</p>\n<div class=\"warn\">Al terminar, revisá que no haya quedado nada sin contestar.</div></div>","ex":[{"t":"fill","q":"1. Calculá","labels":["7 + 7","40 + 6","19 + 1","25 + 10"],"a":["14","46","20","35"]},{"t":"fill","q":"2. Completá para llegar a 10","labels":["4 + __","9 + __"],"a":["6","1"]},{"t":"order","q":"3. Ordená de menor a mayor","items":["43","34","40","14"],"a":["14","34","40","43"]},{"t":"choice","q":"4. 56 ___ 65","o":["&lt;","&gt;","="],"a":0},{"t":"fill","q":"5. ¿Qué número está abajo del 27 en el cuadro?","labels":[""],"a":["37"]},{"t":"fill","q":"6. Tenía <b>12</b> bolitas y gané <b>7</b>. ¿Cuántas tengo?","labels":["Respuesta"],"a":["19"]},{"t":"fill","q":"7. Había <b>18</b> pájaros y se fueron <b>9</b>. ¿Cuántos quedaron?","labels":["Respuesta"],"a":["9"]},{"t":"fill","q":"8. Descomponé","labels":["84 ="],"a":["80+4"]},{"t":"fill","q":"9. Resolvé","labels":["33 + 25"],"a":["58"]}]}]},{"id":"lengua","name":"Lengua","emo":"📖","tag":"","desc":"Nombres, calendario, cuentos, rimas y listas","c1":"#3E9E5F","c2":"#86C252","units":[{"id":"l1","dot":"📅","name":"Nombres y calendario","title":"Nombres, días y meses","sub":"Leer nombres, el calendario y carteles","rules":"\n<div class=\"rsec\"><h4>La semana y el año</h4>\n<p class=\"exline\">La semana tiene <b>7 días</b> y el año tiene <b>12 meses</b>. Siempre van en el mismo orden. Recitalos en voz alta para acordarte.</p></div>\n<div class=\"rsec\"><h4>Los nombres de las personas</h4>\n<div class=\"warn\">Los nombres de personas, mascotas y lugares van con <b>mayúscula</b> al principio: <b>M</b>artín, <b>T</b>oby.</div></div>\n<div class=\"rsec\"><h4>Leer palabras</h4>\n<p class=\"exline\">Si dudás, fijate <b>con qué letra empieza</b> y <b>con cuál termina</b>. Eso ayuda a saber qué dice.</p></div>","ex":[{"t":"order","q":"Ordená los días de la semana","items":["miércoles","lunes","viernes","martes","jueves"],"a":["lunes","martes","miércoles","jueves","viernes"]},{"t":"fill","q":"Completá","labels":["Después del martes viene el…","Antes del domingo está el…"],"a":["miercoles","sabado"]},{"t":"choice","q":"¿Cuál de estas palabras es un <b>mes</b>?","o":["marzo","lunes","verano"],"a":0},{"t":"order","q":"Ordená estos meses","items":["marzo","enero","abril","febrero"],"a":["enero","febrero","marzo","abril"]},{"t":"choice","q":"¿Qué cartel le ponés a la caja de los lápices?","o":["LÁPICES","PELOTAS","LIBROS"],"a":0},{"t":"choice","q":"¿Qué palabra empieza igual que <b>MAMÁ</b>?","o":["MESA","PATO","SOL"],"a":0},{"t":"choice","q":"¿Cuál está bien escrito?","o":["Lucía","lucía"],"a":0}]},{"id":"l2","dot":"🐺","name":"Cuentos y poesía","title":"Cuentos tradicionales, rimas y adivinanzas","sub":"Escuchar, leer y jugar con las palabras","rules":"\n<div class=\"rsec\"><h4>Cuentos tradicionales</h4>\n<p class=\"exline\">Son cuentos que se cuentan desde hace muchísimos años. Todo cuento tiene un <b>principio</b>, algo que <b>pasa</b> y un <b>final</b>.</p></div>\n<div class=\"rsec\"><h4>Rimas</h4>\n<p class=\"exline\">Dos palabras riman cuando <b>terminan con el mismo sonido</b>: s<b>ol</b> y c<b>ol</b>.</p></div>\n<div class=\"rsec\"><h4>Adivinanzas</h4>\n<p class=\"exline\">Dan <b>pistas</b> sin decir el nombre. Ejemplo: <i>«Oro parece, plata no es»</i>. Prestá atención a cada pista.</p></div>","ex":[{"t":"choice","q":"En «Caperucita Roja», ¿a quién va a visitar Caperucita?","o":["A su abuela","A su tía","Al cazador"],"a":0},{"t":"choice","q":"En «Los tres chanchitos», ¿qué casa no pudo voltear el lobo?","o":["La de paja","La de madera","La de ladrillos"],"a":2},{"t":"order","q":"Ordená el cuento «Los tres chanchitos»","items":["El lobo sopla la casa de paja","Los chanchitos construyen sus casas","El lobo no puede voltear la casa de ladrillos"],"a":["Los chanchitos construyen sus casas","El lobo sopla la casa de paja","El lobo no puede voltear la casa de ladrillos"]},{"t":"choice","q":"¿Qué palabra rima con <b>GATO</b>?","o":["PATO","PERRO","MESA"],"a":0},{"t":"choice","q":"¿Qué palabra rima con <b>LUNA</b>?","o":["CUNA","SOL","LUZ"],"a":0},{"t":"choice","q":"¿Qué palabra rima con <b>CAMIÓN</b>?","o":["RATÓN","AUTO","RUEDA"],"a":0},{"t":"choice","q":"Adiviná: <i>«Blanca por dentro, verde por fuera; si quieres que te lo diga, espera.»</i>","o":["La pera","La manzana","La banana"],"a":0},{"t":"choice","q":"Adiviná: <i>«Tengo agujas y no sé coser, tengo números y no sé leer.»</i>","o":["El reloj","El libro","La tijera"],"a":0},{"t":"open","q":"Inventá una rima con tu nombre","model":"Que la palabra que elija termine con el mismo sonido que su nombre. Puede ser divertida o sin sentido: lo que importa es que rime."}]},{"id":"l3","dot":"📝","name":"Listas y letras","title":"Escribir listas","sub":"Listas con un propósito · qué letras van","rules":"\n<div class=\"rsec\"><h4>¿Para qué sirve una lista?</h4>\n<p class=\"exline\">Para no olvidarse de nada. Cada lista tiene un <b>tema</b>, y solo van cosas de ese tema. Ejemplo, lista del cumpleaños: globos, torta, velas.</p></div>\n<div class=\"rsec\"><h4>¿Qué letras van?</h4>\n<div class=\"warn\">Decí la palabra <b>despacio</b>, separando los sonidos, y escribí una letra por cada sonido. Después leela con el dedo para ver si dice lo que querías.</div></div>","ex":[{"t":"choice","q":"¿Qué va en la lista de las compras del súper?","o":["leche","lunes","Lucía"],"a":0},{"t":"choice","q":"¿Qué <b>NO</b> va en una lista de útiles?","o":["lápiz","goma","pelota"],"a":2},{"t":"choice","q":"Para hacer una torta necesitamos…","o":["harina, huevos y azúcar","pelota, auto y muñeca","lunes, martes y jueves"],"a":0},{"t":"fill","q":"Escribí la palabra completa","labels":["CA_A (donde vivimos)","SO_ (brilla en el cielo)","ME_A (para comer)"],"a":["casa","sol","mesa"]},{"t":"choice","q":"¿Con qué letra empieza <b>PELOTA</b>?","o":["P","B","T"],"a":0},{"t":"choice","q":"¿Cuántas letras tiene <b>SOL</b>?","o":["3","2","4"],"a":0},{"t":"open","q":"Escribí una lista de tus 4 juegos preferidos","model":"Una cosa por renglón. Revisá juntos que cada palabra diga lo que quiso escribir, leyéndola con el dedo."},{"t":"open","q":"Escribí la lista de los personajes de un cuento que conozcas","model":"Que nombre a todos los personajes importantes del cuento. Los nombres propios, con mayúscula."}]},{"id":"l4","dot":"🔁","name":"Escribir en orden","title":"Escribir siguiendo un orden y revisar","sub":"Primero, después, al final · separar y revisar","rules":"\n<div class=\"rsec\"><h4>Primero, después, al final</h4>\n<p class=\"exline\">Para contar algo que se hace en pasos, pensá qué pasa <b>primero</b>, qué <b>después</b> y qué <b>al final</b>. Ejemplo, hacer la cama: primero estiro la sábana, después la frazada, al final acomodo la almohada.</p></div>\n<div class=\"rsec\"><h4>Revisar lo que escribí</h4>\n<div class=\"warn\"><b>Señalá con el dedo</b> cada palabra mientras la leés. Así te das cuenta si <b>falta</b> una letra, si <b>sobra</b> alguna o si dos palabras quedaron pegadas.</div></div>","ex":[{"t":"order","q":"Ordená los pasos para lavarse los dientes","items":["Me enjuago la boca","Pongo pasta en el cepillo","Me cepillo los dientes"],"a":["Pongo pasta en el cepillo","Me cepillo los dientes","Me enjuago la boca"]},{"t":"order","q":"Ordená los pasos para plantar una semilla","items":["Riego la tierra","Hago un pozo","Pongo la semilla"],"a":["Hago un pozo","Pongo la semilla","Riego la tierra"]},{"t":"choice","q":"¿Cuál está bien escrito?","o":["EL SOL BRILLA","ELSOLBRILLA","EL SOLBRI LLA"],"a":0},{"t":"choice","q":"Leé con el dedo: <b>MESSA</b>. ¿Qué le pasa?","o":["Le sobra una letra","Le falta una letra","Está bien"],"a":0},{"t":"choice","q":"Leé con el dedo: <b>PELTA</b>. ¿Qué le pasa?","o":["Le sobra una letra","Le falta una letra","Está bien"],"a":1},{"t":"choice","q":"La persona que escribe un libro es…","o":["el autor o la autora","el lector o la lectora","el librero"],"a":0},{"t":"open","q":"Escribí 3 oraciones sobre tu día: qué hacés primero, qué después y qué al final","model":"Tres oraciones en orden. Revisá juntos que estén separadas las palabras y que no falten letras."}]},{"id":"lsim","dot":"📝","name":"Simulacro","title":"Simulacro de Lengua","sub":"Todo junto","rules":"\n<div class=\"rsec\"><h4>Antes de empezar</h4>\n<p class=\"exline\">Leé cada pregunta despacio. Si no estás segura o seguro, volvé a leerla.</p>\n<div class=\"warn\">Al terminar, leé con el dedo lo que escribiste.</div></div>","ex":[{"t":"choice","q":"1. ¿Qué día viene después del jueves?","o":["viernes","miércoles","sábado"],"a":0},{"t":"choice","q":"2. ¿Qué palabra rima con <b>FLOR</b>?","o":["COLOR","FLORES","ROSA"],"a":0},{"t":"fill","q":"3. Escribí la palabra completa","labels":["PA_O (un ave que nada)"],"a":["pato"]},{"t":"choice","q":"4. ¿Qué <b>NO</b> va en una lista de frutas?","o":["manzana","pera","zapato"],"a":2},{"t":"order","q":"5. Ordená los pasos para ponerse las zapatillas","items":["Me ato los cordones","Me pongo las medias","Me pongo las zapatillas"],"a":["Me pongo las medias","Me pongo las zapatillas","Me ato los cordones"]},{"t":"choice","q":"6. ¿Cuál está bien escrito?","o":["Ana juega en el patio.","anajuegaenelpatio","ana juega en el patio"],"a":0},{"t":"open","q":"7. Escribí una adivinanza sobre un animal","model":"Que dé pistas sin decir el nombre del animal."}]}]}]};
